SELECT l.id, l.terminal_id AS terminalId, t.terminal_name AS terminalName, l.action_type AS actionType, l.command, l.command_result AS commandResult, l.executed_by AS executedBy, l.status, DATE_FORMAT(l.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(l.completed_at, '%Y-%m-%d %H:%i:%s') AS completedAt FROM tb_device_maintenance_log l LEFT JOIN tb_terminal t ON l.terminal_id = t.terminal_id
AND l.terminal_id = #{terminalId}
AND l.action_type = #{actionType}
AND l.created_at >= #{startDate}
AND l.created_at <= CONCAT(#{endDate}, ' 23:59:59')
ORDER BY l.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM tb_device_maintenance_log l


        AND l.terminal_id = #{terminalId}


        AND l.action_type = #{actionType}


        AND l.created_at >= #{startDate}


        AND l.created_at <= CONCAT(#{endDate}, ' 23:59:59')
